args.sparql:
SELECT ?actor ?actorLabel (COUNT(DISTINCT ?film) AS ?count)
WHERE {
  ?film wdt:P161 wd:Q227129.
  ?film wdt:P161 ?actor.
  FILTER(?actor != wd:Q227129)
  OPTIONAL { ?actor rdfs:label ?actorLabel FILTER(LANG(?actorLabel) = "en") }
}
GROUP BY ?actor ?actorLabel
HAVING (COUNT(DISTINCT ?film) > 2)
